(async () => {
const events=[]; let release, settled=false, count=0;
const source={ [Symbol.iterator]() { return {
  next() { if(count++===0) return {value:7,done:false};
    return {get done(){events.push('done');return true;},get value(){events.push('value');
      return {then(resolve){events.push('then');release=resolve;}};}};
  }, return(){events.push('unexpected-close');return {};}
};}};
const work=Array.fromAsync(source).then(out=>{settled=true;events.push('fulfilled:'+out.join(','));});
for(let i=0;i<12;i++) await Promise.resolve();
console.log('pending',settled,typeof release,events.join('|'));
release(99); await work; console.log(events.join('|'));
})()

(async () => {
let count=0, closes=0, mapped=0; const reason={};
const source={ [Symbol.iterator]() {return {
 next(){return count++===0?{value:2,done:false}:{value:Promise.reject(reason),done:true};},
 return(){closes++;return {};}
};}};
let caught=false;
try {await Array.fromAsync(source,x=>{mapped++;return x;});}catch(error){caught=error===reason;}
console.log(caught,count,closes,mapped);
})()

