(async () => {
let reads=0,calls=0;
const iterator={get next(){reads++;return function(){
 if(this!==iterator||arguments.length!==0) throw Error('receiver or arguments');
 calls++;if(calls===1){Object.defineProperty(iterator,'next',{value(){throw Error('re-read');}});return {value:3,done:false};}
 return {done:true};
};}};
const source={[Symbol.iterator](){return iterator;}};
const out=await Array.fromAsync(source);console.log(reads,calls,out.join(','));
})()

