(async () => {
const reason={},events=[];let release,settled=false;
const iterator={next(){return {value:1,done:false};},
 return(){events.push('return:'+arguments.length+':'+(this===iterator));return {
 get done(){events.push('done');return true;},get value(){events.push('value');return {
 then(resolve){events.push('then');release=resolve;}};}};}
};
const work=Array.fromAsync({[Symbol.iterator](){return iterator;}},()=>{throw reason;})
 .catch(e=>{settled=true;events.push('same:'+(e===reason));});
for(let i=0;i<14;i++)await Promise.resolve();
console.log('pending',settled,typeof release,events.join('|'));
release(99);await work;console.log(events.join('|'));
})()

