(async () => {
let checked=0;
for(const original of [undefined,null,false,-0,17n,Symbol('x'),'\ud800']){
 let closed=0;
 const source={[Symbol.iterator](){return {
 next(){return {value:1,done:false};},
 return(){closed++;try{throw 'nested';}catch(e){}return {done:true,value:Promise.resolve(9)};}
 };}};
 let caught=false;try{await Array.fromAsync(source,()=>{throw original;});}catch(e){caught=Object.is(e,original);}
 if(!caught||closed!==1)throw Error('identity');checked++;
}
console.log('exact',checked);
})()

(async () => {
const original={};let final=0;
function* source(){try{yield 4;return Promise.reject(original);}finally{final++;}}
let caught=false;try{await Array.fromAsync(source());}catch(e){caught=e===original;}
console.log(caught,final);
})()

(async () => {
const original={},events=[];let release,settled=false;
function* source(){try{yield 3;}finally{events.push('finally');yield {then(resolve){events.push('then');release=resolve;}};events.push('after-yield');}}
const iterator=source();
const work=Array.fromAsync(iterator,()=>{throw original;}).catch(e=>{settled=true;events.push('same:'+(e===original));});
for(let i=0;i<14;i++)await Promise.resolve();
console.log('pending',settled,typeof release,events.join('|'));
release(0);await work;console.log(events.join('|'));console.log(iterator.next().done,events.join('|'));
})()

