(async () => {
const releases=[],reasons=[{},{}],results=[];
function start(index){return Array.fromAsync({[Symbol.iterator](){return {
 next(){return {value:index,done:false};},return(){return {done:true,value:{then(resolve){releases[index]=resolve;}}};}
};}},()=>{throw reasons[index];}).catch(e=>results.push(index+':'+(e===reasons[index])));}
const first=start(0),second=start(1);
for(let i=0;i<20;i++)await Promise.resolve();
console.log('waiting',results.length,releases.length);
releases[1](1);await second;releases[0](0);await first;console.log(results.join('|'));
})()

(async () => {
const mode="missing";const original={},other={};let calls=0,done=0,value=0;
const iterator={next(){return {value:1,done:false};}};
if(mode!=='missing')Object.defineProperty(iterator,'return',{get(){
 if(mode==='null')return null;if(mode==='noncallable')return 1;if(mode==='get-throws')throw other;
 return function(){calls++;if(mode==='call-throws')throw other;if(mode==='primitive')return 0;
 return {get done(){done++;if(mode==='done-throws')throw other;return true;},get value(){value++;throw other;}};};
}});
let same=false;try{await Array.fromAsync({[Symbol.iterator](){return iterator;}},()=>{throw original;});}catch(e){same=e===original;}
console.log(same,calls,done,value);
})()

